/* Cyberpunk Neon Theme */
:root {
  --neon-glow: 0 0 20px hsl(var(--primary) / 0.6);
  --neon-text-glow: 0 0 10px hsl(var(--primary) / 0.8);
  --cyber-gradient: linear-gradient(135deg, hsl(var(--primary)), hsl(var(--accent)));
}

.card {
  background: linear-gradient(135deg, hsl(var(--background) / 0.8), hsl(var(--secondary) / 0.9));
  border: 1px solid hsl(var(--primary) / 0.3);
  box-shadow: var(--neon-glow);
  backdrop-filter: blur(10px);
}

.nav-item:hover {
  background: var(--cyber-gradient);
  box-shadow: var(--neon-glow);
  text-shadow: var(--neon-text-glow);
}

.chapter-card {
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  border: 1px solid hsl(var(--primary) / 0.2);
}

.chapter-card:hover {
  transform: translateY(-12px) scale(1.03);
  box-shadow: 0 25px 60px -15px hsl(var(--primary) / 0.5);
  border-color: hsl(var(--primary) / 0.6);
}

h1, h2, h3 {
  text-shadow: var(--neon-text-glow);
}

.btn-primary {
  background: var(--cyber-gradient);
  box-shadow: var(--neon-glow);
}
